import { headers } from 'next/headers';

async function getBaseUrl(): Promise<string> {
  try {
    const headersList = await headers();
    const host = headersList.get('x-forwarded-host') ?? headersList.get('host');
    const protocol = headersList.get('x-forwarded-proto') ?? 'http';
    if (host) {
      return `${protocol}://${host}`;
    }
  } catch {
    // Headers not available during static generation
  }
  return (
    process.env.VERCEL_URL
      ? `https://${process.env.VERCEL_URL}`
      : process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000'
  );
}

async function getDashboardData() {
  const baseUrl = await getBaseUrl();
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch(`${baseUrl}/api/analytics`).then((r) => r.json()),
      fetch(`${baseUrl}/api/notifications`).then((r) => r.json()),
      fetch(`${baseUrl}/api/settings`).then((r) => r.json())
    ]);
    return { analytics, notifications, settings };
  } catch {
    return {
      analytics: { pageViews: 0, uniqueVisitors: 0, bounceRate: 0, avgSessionDuration: 0 },
      notifications: [],
      settings: { theme: 'light', notifications: false, language: 'en' }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <section>
        <h3>Analytics</h3>
        <ul>
          <li>Page views: {analytics.pageViews}</li>
          <li>Unique visitors: {analytics.uniqueVisitors}</li>
          <li>Bounce rate: {analytics.bounceRate}%</li>
          <li>Avg session: {analytics.avgSessionDuration}s</li>
        </ul>
      </section>

      <section>
        <h3>Notifications</h3>
        <ul>
          {notifications.map((n: { id: number; message: string; read: boolean }) => (
            <li key={n.id}>
              {n.message} {n.read ? '(read)' : '(new)'}
            </li>
          ))}
        </ul>
      </section>

      <section>
        <h3>Settings</h3>
        <ul>
          <li>Theme: {settings.theme}</li>
          <li>Notifications: {settings.notifications ? 'On' : 'Off'}</li>
          <li>Language: {settings.language}</li>
        </ul>
      </section>
    </div>
  );
}

